import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"10、【履】 兑下乾上","description":"横渠易说 - 10、【履】 兑下乾上","frontmatter":{"title":"10、【履】 兑下乾上","description":"横渠易说 - 10、【履】 兑下乾上"},"headers":[],"relativePath":"zh/classics/hengqu/012.md","filePath":"zh/classics/hengqu/012.md"}'),l={name:"zh/classics/hengqu/012.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_10、【履】-兑下乾上" tabindex="-1">10、【履】 兑下乾上 <a class="header-anchor" href="#_10、【履】-兑下乾上" aria-label="Permalink to “10、【履】 兑下乾上”">​</a></h1><h3 id="彖曰-履-柔履刚也。说而应乎乾-是以履虎尾-不咥人-亨。" tabindex="-1">彖曰：履，柔履刚也。说而应乎乾，是以履虎尾，不咥人，亨。 <a class="header-anchor" href="#彖曰-履-柔履刚也。说而应乎乾-是以履虎尾-不咥人-亨。" aria-label="Permalink to “彖曰：履，柔履刚也。说而应乎乾，是以履虎尾，不咥人，亨。”">​</a></h3><p>说虽应乾而二不累五也。刚中正，履帝位而不疚，光明也。 无阴柔之累，故不疚，此所以正一卦之德也。</p><h3 id="象曰-上天下泽-履-君子以辩上下-定民志。" tabindex="-1">象曰：上天下泽，履，君子以辩上下，定民志。 <a class="header-anchor" href="#象曰-上天下泽-履-君子以辩上下-定民志。" aria-label="Permalink to “象曰：上天下泽，履，君子以辩上下，定民志。”">​</a></h3><h3 id="初九-素履-往无咎。-象曰-素履之往-独行愿也。" tabindex="-1">初九，素履，往无咎。 象曰：素履之往，独行愿也。 <a class="header-anchor" href="#初九-素履-往无咎。-象曰-素履之往-独行愿也。" aria-label="Permalink to “初九，素履，往无咎。 象曰：素履之往，独行愿也。”">​</a></h3><p>阴累不乾，无应于上，故其履洁素。</p><h3 id="九二-履道坦坦-幽人贞吉。-象曰-幽人贞吉-中不自乱也。" tabindex="-1">九二，履道坦坦，幽人贞吉。 象曰：“幽人贞吉”，中不自乱也。 <a class="header-anchor" href="#九二-履道坦坦-幽人贞吉。-象曰-幽人贞吉-中不自乱也。" aria-label="Permalink to “九二，履道坦坦，幽人贞吉。 象曰：“幽人贞吉”，中不自乱也。”">​</a></h3><p>中正不累，无援于上，故中不自乱，得幽人之正。</p><h3 id="六三-眇能视-跛能履。履虎尾-咥人凶。武人为于六君。-象曰-眇能视-不足以有明也-跛能履-不足以与行也。咥人之凶-位不当也。-武人为于大君-志刚也。" tabindex="-1">六三，眇能视，跛能履。履虎尾，咥人凶。武人为于六君。 象曰：“眇能视”，不足以有明也；“跛能履”，不足以与行也。咥人之凶，位不当也。“武人为于大君”，志刚也。 <a class="header-anchor" href="#六三-眇能视-跛能履。履虎尾-咥人凶。武人为于六君。-象曰-眇能视-不足以有明也-跛能履-不足以与行也。咥人之凶-位不当也。-武人为于大君-志刚也。" aria-label="Permalink to “六三，眇能视，跛能履。履虎尾，咥人凶。武人为于六君。 象曰：“眇能视”，不足以有明也；“跛能履”，不足以与行也。咥人之凶，位不当也。“武人为于大君”，志刚也。”">​</a></h3><p>大君者，为众爻之主也。武人者，刚而不德也。</p><h3 id="九四-履虎尾愬愬-终吉。-象曰-愬愬终吉-志行也。" tabindex="-1">九四，履虎尾愬愬，终吉。 象曰：“愬愬终吉”，志行也。 <a class="header-anchor" href="#九四-履虎尾愬愬-终吉。-象曰-愬愬终吉-志行也。" aria-label="Permalink to “九四，履虎尾愬愬，终吉。 象曰：“愬愬终吉”，志行也。”">​</a></h3><p>三五不累于己，处多惧之地，近比于三，能常自危，则志愿终吉。阳居阴，故不自肆，常自危也。</p><h3 id="九五-夬履贞厉-象曰-夬履贞厉-位正当也。" tabindex="-1">九五，“夬履贞厉”， 象曰：“夬履贞厉”，位正当也。 <a class="header-anchor" href="#九五-夬履贞厉-象曰-夬履贞厉-位正当也。" aria-label="Permalink to “九五，“夬履贞厉”， 象曰：“夬履贞厉”，位正当也。”">​</a></h3><h3 id="上九-视履考祥-其旋元吉。-象曰-元吉在上-大有庆也。" tabindex="-1">上九，视履考祥，其旋元吉。 象曰：元吉在上，大有庆也。 <a class="header-anchor" href="#上九-视履考祥-其旋元吉。-象曰-元吉在上-大有庆也。" aria-label="Permalink to “上九，视履考祥，其旋元吉。 象曰：元吉在上，大有庆也。”">​</a></h3><p>视所履以考求其吉，莫如旋而及下，则获应而有喜也。 乘刚未安，其进也宁旋。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
